#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_direct_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int C_out,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int pD, int pH, int pW,
    int dD, int dH, int dW,
    int groups
) {
    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    int oc_local = threadIdx.y;
    int oc_block = blockIdx.y;
    int n_od = blockIdx.z;

    int oc = oc_block * blockDim.y + oc_local;
    int n = n_od / D_out;
    int od = n_od % D_out;

    if (n >= N || oc >= C_out) return;

    for (int oh = 0; oh < H_out; oh++) {
        if (ow >= W_out) continue;

        int id_base = od * sD - pD;
        int ih_base = oh * sH - pH;
        int iw_base = ow * sW - pW;

        float acc = 0.0f;

        int c_in_per_group = C_in / groups;
        int c_out_per_group = C_out / groups;
        int group_idx = oc / c_out_per_group;
        int oc_in_group = oc % c_out_per_group;
        int c_in_start = group_idx * c_in_per_group;

        for (int ic = 0; ic < c_in_per_group; ic++) {
            int ic_global = c_in_start + ic;
            for (int kd = 0; kd < kD; kd++) {
                int id = id_base + kd * dD;
                if (id < 0 || id >= D_in) continue;

                for (int kh = 0; kh < kH; kh++) {
                    int ih = ih_base + kh * dH;
                    if (ih < 0 || ih >= H_in) continue;

                    for (int kw = 0; kw < kW; kw++) {
                        int iw = iw_base + kw * dW;
                        if (iw < 0 || iw >= W_in) continue;

                        int input_idx = ((n * C_in + ic_global) * D_in + id) * H_in * W_in + ih * W_in + iw;
                        int weight_idx = ((oc * c_in_per_group + ic) * kD + kd) * kH * kW + kh * kW + kw;

                        acc += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }

        if (bias != nullptr) {
            acc += bias[oc];
        }

        int output_idx = ((n * C_out + oc) * D_out + od) * H_out * W_out + oh * W_out + ow;
        output[output_idx] = acc;
    }
}

torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d, int stride_h, int stride_w,
    int padding_d, int padding_h, int padding_w,
    int dilation_d, int dilation_h, int dilation_w,
    int groups
) {
    int N = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    int C_out = weight.size(0);
    int kD = weight.size(2);
    int kH = weight.size(3);
    int kW = weight.size(4);

    int D_out = (D_in + 2 * padding_d - dilation_d * (kD - 1) - 1) / stride_d + 1;
    int H_out = (H_in + 2 * padding_h - dilation_h * (kH - 1) - 1) / stride_h + 1;
    int W_out = (W_in + 2 * padding_w - dilation_w * (kW - 1) - 1) / stride_w + 1;

    auto output = torch::empty({N, C_out, D_out, H_out, W_out}, input.options());

    dim3 threads(32, 4);
    dim3 blocks((W_out + threads.x - 1) / threads.x, (C_out + threads.y - 1) / threads.y, N * D_out);

    const float* bias_ptr = bias.defined() ? bias.data_ptr<float>() : nullptr;

    conv3d_direct_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, C_out,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        kD, kH, kW,
        stride_d, stride_h, stride_w,
        padding_d, padding_h, padding_w,
        dilation_d, dilation_h, dilation_w,
        groups
    );

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv3d_forward", &conv3d_forward_cuda, "Conv3D forward (CUDA)");
