CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Interior kernel: no bounds checks, all taps guaranteed valid
__global__ void conv3d_interior_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int C_out,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int pD, int pH, int pW,
    int dD, int dH, int dW,
    // interior region bounds [od_start, od_end) x [oh_start, oh_end) x [ow_start, ow_end)
    int od_start, int od_end,
    int oh_start, int oh_end,
    int ow_start, int ow_end
) {
    int ow_rel = blockIdx.x * blockDim.x + threadIdx.x;
    int oh_rel = blockIdx.y * blockDim.y + threadIdx.y;
    int idx_z   = blockIdx.z;

    int interior_W = ow_end - ow_start;
    int interior_H = oh_end - oh_start;
    int interior_D = od_end - od_start;

    if (ow_rel >= interior_W || oh_rel >= interior_H) return;

    int ow = ow_rel + ow_start;
    int oh = oh_rel + oh_start;

    // decode idx_z -> (n, oc, od_rel)
    int od_rel = idx_z % interior_D;
    int tmp    = idx_z / interior_D;
    int oc     = tmp % C_out;
    int n      = tmp / C_out;

    if (n >= N) return;

    int od = od_rel + od_start;

    int id_base = od * sD - pD;
    int ih_base = oh * sH - pH;
    int iw_base = ow * sW - pW;

    float acc = (bias != nullptr) ? bias[oc] : 0.0f;

    int c_in_per_group = C_in;
    int c_out_per_group = C_out;
    int group_idx = 0;
    int c_in_start = 0;
    int c_in_end = C_in;

    for (int ci = c_in_start; ci < c_in_end; ci++) {
        int w_ci = ci - c_in_start;
        for (int kd = 0; kd < kD; kd++) {
            int id = id_base + kd * dD;
            for (int kh = 0; kh < kH; kh++) {
                int ih = ih_base + kh * dH;
                for (int kw = 0; kw < kW; kw++) {
                    int iw = iw_base + kw * dW;
                    float in_val = input[((n * C_in + ci) * D_in + id) * H_in * W_in + ih * W_in + iw];
                    float w_val  = weight[((oc * c_in_per_group + w_ci) * kD + kd) * kH * kW + kh * kW + kw];
                    acc += in_val * w_val;
                }
            }
        }
    }

    output[((n * C_out + oc) * D_out + od) * H_out * W_out + oh * W_out + ow] = acc;
}

// Edge kernel: full bounds checks for boundary output positions
__global__ void conv3d_edge_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int C_out,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int pD, int pH, int pW,
    int dD, int dH, int dW,
    // interior region to skip
    int od_start, int od_end,
    int oh_start, int oh_end,
    int ow_start, int ow_end
) {
    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    int idx_z = blockIdx.z;

    if (ow >= W_out || oh >= H_out) return;

    int od = idx_z % D_out;
    int tmp = idx_z / D_out;
    int oc  = tmp % C_out;
    int n   = tmp / C_out;

    if (n >= N) return;

    // skip interior positions (handled by interior kernel)
    if (od >= od_start && od < od_end &&
        oh >= oh_start && oh < oh_end &&
        ow >= ow_start && ow < ow_end) return;

    int id_base = od * sD - pD;
    int ih_base = oh * sH - pH;
    int iw_base = ow * sW - pW;

    float acc = (bias != nullptr) ? bias[oc] : 0.0f;

    int c_in_per_group = C_in;
    int c_in_start = 0;

    for (int ci = c_in_start; ci < C_in; ci++) {
        int w_ci = ci - c_in_start;
        for (int kd = 0; kd < kD; kd++) {
            int id = id_base + kd * dD;
            if (id < 0 || id >= D_in) continue;
            for (int kh = 0; kh < kH; kh++) {
                int ih = ih_base + kh * dH;
                if (ih < 0 || ih >= H_in) continue;
                for (int kw = 0; kw < kW; kw++) {
                    int iw = iw_base + kw * dW;
                    if (iw < 0 || iw >= W_in) continue;
                    float in_val = input[((n * C_in + ci) * D_in + id) * H_in * W_in + ih * W_in + iw];
                    float w_val  = weight[((oc * c_in_per_group + w_ci) * kD + kd) * kH * kW + kh * kW + kw];
                    acc += in_val * w_val;
                }
            }
        }
    }

    output[((n * C_out + oc) * D_out + od) * H_out * W_out + oh * W_out + ow] = acc;
}

torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias_opt,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> dilation,
    int64_t groups
) {
    int N    = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    int C_out = weight.size(0);
    int kD    = weight.size(2);
    int kH    = weight.size(3);
    int kW    = weight.size(4);

    int sD = stride[0], sH = stride[1], sW = stride[2];
    int pD = padding[0], pH = padding[1], pW = padding[2];
    int dD = dilation[0], dH = dilation[1], dW = dilation[2];

    int D_out = (D_in + 2 * pD - dD * (kD - 1) - 1) / sD + 1;
    int H_out = (H_in + 2 * pH - dH * (kH - 1) - 1) / sH + 1;
    int W_out = (W_in + 2 * pW - dW * (kW - 1) - 1) / sW + 1;

    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    const float* input_ptr  = input.data_ptr<float>();
    const float* weight_ptr = weight.data_ptr<float>();
    const float* bias_ptr   = nullptr;
    if (bias_opt.has_value() && bias_opt.value().defined()) {
        bias_ptr = bias_opt.value().data_ptr<float>();
    }
    float* output_ptr = output.data_ptr<float>();

    // Compute interior region: output positions where all kernel taps are in-bounds
    // For dim d: id_base = od*sD - pD >= 0  => od >= ceil(pD/sD)
    //            id_base + (kD-1)*dD < D_in  => od < (D_in - (kD-1)*dD + pD) / sD
    auto ceil_div = [](int a, int b) { return (a + b - 1) / b; };

    int od_start = (pD > 0) ? ceil_div(pD, sD) : 0;
    int oh_start = (pH > 0) ? ceil_div(pH, sH) : 0;
    int ow_start = (pW > 0) ? ceil_div(pW, sW) : 0;

    // largest od where id_base + (kD-1)*dD < D_in:
    // od*sD - pD + (kD-1)*dD < D_in  => od < (D_in - (kD-1)*dD + pD) / sD
    int od_end = (D_in - (kD - 1) * dD + pD) / sD;  // floor division intentional
    int oh_end = (H_in - (kH - 1) * dH + pH) / sH;
    int ow_end = (W_in - (kW - 1) * dW + pW) / sW;

    if (od_end > D_out) od_end = D_out;
    if (oh_end > H_out) oh_end = H_out;
    if (ow_end > W_out) ow_end = W_out;
    if (od_start > od_end) od_start = od_end;
    if (oh_start > oh_end) oh_start = oh_end;
    if (ow_start > ow_end) ow_start = ow_end;

    int interior_D = od_end - od_start;
    int interior_H = oh_end - oh_start;
    int interior_W = ow_end - ow_start;

    bool has_interior = (interior_D > 0) && (interior_H > 0) && (interior_W > 0);
    bool has_edge     = !(od_start == 0 && od_end == D_out &&
                          oh_start == 0 && oh_end == H_out &&
                          ow_start == 0 && ow_end == W_out);

    dim3 block(32, 8, 1);

    if (has_interior) {
        dim3 grid(
            (interior_W + block.x - 1) / block.x,
            (interior_H + block.y - 1) / block.y,
            N * C_out * interior_D
        );
        conv3d_interior_kernel<<<grid, block>>>(
            input_ptr, weight_ptr, bias_ptr, output_ptr,
            N, C_in, C_out,
            D_in, H_in, W_in,
            D_out, H_out, W_out,
            kD, kH, kW,
            sD, sH, sW,
            pD, pH, pW,
            dD, dH, dW,
            od_start, od_end,
            oh_start, oh_end,
            ow_start, ow_end
        );
    }

    if (has_edge) {
        dim3 grid_e(
            (W_out + block.x - 1) / block.x,
            (H_out + block.y - 1) / block.y,
            N * C_out * D_out
        );
        conv3d_edge_kernel<<<grid_e, block>>>(
            input_ptr, weight_ptr, bias_ptr, output_ptr,
            N, C_in, C_out,
            D_in, H_in, W_in,
            D_out, H_out, W_out,
            kD, kH, kW,
            sD, sH, sW,
            pD, pH, pW,
            dD, dH, dW,
            od_start, od_end,
            oh_start, oh_end,
            ow_start, ow_end
        );
    }

    return output;
}
