# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <c10/util/Optional.h>
#include <vector>

// Branchless interior kernel: no bounds checks, all taps guaranteed valid.
// Specialized for C_in=3, KD=3, KH=5, KW=7.
__global__ void conv3d_interior_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int KD, int KH, int KW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dil_d, int dil_h, int dil_w,
    int od_start, int oh_start, int ow_start,
    int od_end,   int oh_end,   int ow_end
) {
    // Each thread computes one (n, oc, od, oh, ow)
    int ow = ow_start + (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int oh = oh_start + (int)(blockIdx.y * blockDim.y + threadIdx.y);
    int tmp = blockIdx.z;
    int od  = od_start + tmp % (od_end - od_start);
    tmp /= (od_end - od_start);
    int oc = tmp % C_out;
    int n  = tmp / C_out;

    if (ow >= ow_end || oh >= oh_end) return;
    if (n >= N) return;

    int id_base = od * stride_d - pad_d;
    int ih_base = oh * stride_h - pad_h;
    int iw_base = ow * stride_w - pad_w;

    float acc = 0.0f;
    // C_in=3, KD=3, KH=5, KW=7 unrolled
    const float* w_ptr = weight + oc * (C_in * KD * KH * KW);
    const float* in_ptr = input + n * (C_in * D_in * H_in * W_in);

    #pragma unroll
    for (int ci = 0; ci < 3; ++ci) {
        const float* in_c = in_ptr + ci * (D_in * H_in * W_in);
        #pragma unroll
        for (int kd = 0; kd < 3; ++kd) {
            int id = id_base + kd * dil_d;
            const float* in_d = in_c + id * (H_in * W_in);
            #pragma unroll
            for (int kh = 0; kh < 5; ++kh) {
                int ih = ih_base + kh * dil_h;
                const float* in_h = in_d + ih * W_in;
                #pragma unroll
                for (int kw = 0; kw < 7; ++kw) {
                    int iw = iw_base + kw * dil_w;
                    acc += in_h[iw] * (*w_ptr);
                    ++w_ptr;
                }
            }
        }
    }

    if (bias) acc += bias[oc];
    output[((n * C_out + oc) * D_out + od) * H_out * W_out + oh * W_out + ow] = acc;
}

// Guarded edge kernel: identical but with bounds checks.
__global__ void conv3d_edge_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int KD, int KH, int KW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dil_d, int dil_h, int dil_w,
    // interior region to skip
    int int_od_start, int int_oh_start, int int_ow_start,
    int int_od_end,   int int_oh_end,   int int_ow_end
) {
    int ow = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int oh = (int)(blockIdx.y * blockDim.y + threadIdx.y);
    int tmp = blockIdx.z;
    int od  = tmp % D_out;
    tmp /= D_out;
    int oc = tmp % C_out;
    int n  = tmp / C_out;

    if (ow >= W_out || oh >= H_out || n >= N) return;

    // Skip interior voxels (already computed)
    if (od >= int_od_start && od < int_od_end &&
        oh >= int_oh_start && oh < int_oh_end &&
        ow >= int_ow_start && ow < int_ow_end) return;

    int id_base = od * stride_d - pad_d;
    int ih_base = oh * stride_h - pad_h;
    int iw_base = ow * stride_w - pad_w;

    float acc = 0.0f;
    const float* w_ptr = weight + oc * (C_in * KD * KH * KW);
    const float* in_ptr = input + n * (C_in * D_in * H_in * W_in);

    for (int ci = 0; ci < C_in; ++ci) {
        const float* in_c = in_ptr + ci * (D_in * H_in * W_in);
        for (int kd = 0; kd < KD; ++kd) {
            int id = id_base + kd * dil_d;
            for (int kh = 0; kh < KH; ++kh) {
                int ih = ih_base + kh * dil_h;
                for (int kw = 0; kw < KW; ++kw) {
                    int iw = iw_base + kw * dil_w;
                    float val = 0.0f;
                    if (id >= 0 && id < D_in && ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
                        val = in_c[id * (H_in * W_in) + ih * W_in + iw];
                    }
                    acc += val * (*w_ptr);
                    ++w_ptr;
                }
            }
        }
    }

    if (bias) acc += bias[oc];
    output[((n * C_out + oc) * D_out + od) * H_out * W_out + oh * W_out + ow] = acc;
}

torch::Tensor conv3d_forward_cuda(
    const torch::Tensor& input,
    const torch::Tensor& weight,
    const c10::optional<torch::Tensor>& bias,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> dilation,
    int64_t groups
) {
    int N    = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int C_out = weight.size(0);
    int KD = weight.size(2);
    int KH = weight.size(3);
    int KW = weight.size(4);

    int sd = stride[0], sh = stride[1], sw = stride[2];
    int pd = padding[0], ph = padding[1], pw = padding[2];
    int dd = dilation[0], dh = dilation[1], dw = dilation[2];

    int D_out = (D_in + 2*pd - dd*(KD-1) - 1) / sd + 1;
    int H_out = (H_in + 2*ph - dh*(KH-1) - 1) / sh + 1;
    int W_out = (W_in + 2*pw - dw*(KW-1) - 1) / sw + 1;

    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    const float* in_data  = input.data_ptr<float>();
    const float* w_data   = weight.data_ptr<float>();
    const float* b_data   = (bias.has_value() && bias.value().defined()) ? bias.value().data_ptr<float>() : nullptr;
    float* out_data       = output.data_ptr<float>();

    // Interior: output positions where all taps are fully in-bounds
    // id = od*sd - pd + kd*dd, valid when 0 <= id < D_in for all kd in [0,KD-1]
    // od*sd - pd >= 0  =>  od >= ceil(pd/sd)
    // od*sd - pd + (KD-1)*dd <= D_in-1  =>  od <= (D_in-1 - (KD-1)*dd + pd) / sd
    int int_od_start = (pd + sd - 1) / sd;  // ceil(pd/sd)
    int int_oh_start = (ph + sh - 1) / sh;
    int int_ow_start = (pw + sw - 1) / sw;
    int int_od_end   = (D_in - 1 - (KD-1)*dd + pd) / sd + 1;
