// Specialized for C_in=3, KD=3, KH=5, KW=7, stride=dilation=padding=(1,1,1) -> all NO-PAD case.
// The wrapper calls this only when the fast-path guard passes.
__global__ void conv3d_fast_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float*       __restrict__ output,
    int N, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out
