    int id_base = od;
    int ih_base = oh;
    int iw_base = ow;

    // Weight for this output channel: shape (3, 3, 5, 7) = 315 floats
    const float* w = weight + oc * (3 * 3 * 5 * 7);
    // Input base for this (n)
    const float* inp = input + n * (3 * D_in * H_in * W_in);

    float acc = 0.0f;

