        for (int kd = 0; kd < 3; ++kd) {
            int id = id_base + kd;
            const float* inp_d = inp_c + id * (H_in * W_in);
            #pragma unroll
            for (int kh = 0; kh < 5; ++kh) {
                int ih = ih_base + kh;
                const float* inp_h = inp_d + ih * W_in;
                #pragma unroll
                for (int kw = 0; kw < 7; ++kw) {
                    acc += inp_h[iw_base + kw] * w[0 * (3*5*7) + kd*(5*7) + kh*7 + kw];
