    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float*       __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int KD, int KH, int KW,
    int sd, int sh, int sw,
    int pd, int ph, int pw,
    int dd, int dh, int dw
) {
    int ow = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int oh = (int)(blockIdx.y * blockDim.y + threadIdx.y);
    int tmp = blockIdx.z;
    int od  = tmp % D_out; tmp /= D_out;
    int oc  = tmp % C_out; tmp /= C_out;
    int n   = tmp;

    if (ow >= W_out || oh >= H_out || n >= N) return;

    int id_base = od * sd - pd;
    int ih_base = oh * sh - ph;
    int iw_base = ow * sw - pw;

    float acc = 0.0f;
    const float* w = weight + oc * (C_in * KD * KH * KW);
    const float* inp = input + n * (C_in * D_in * H_in * W_in);

    for (int ci = 0; ci < C_in; ++ci) {
        const float* inp_c = inp + ci * (D_in * H_in * W_in);
        for (int kd = 0; kd < KD; ++kd) {
            int id = id_base + kd * dd;
            for (int kh = 0; kh < KH; ++kh) {
                int ih = ih_base + kh * dh;
                for (int kw = 0; kw < KW; ++kw) {
                    int iw = iw_base + kw * dw;
                    float val = 0.0f;
                    if (id >= 0 && id < D_in && ih >= 0 && ih < H_in && iw >= 0 && iw < W_in)
                        val = inp_c[id * (H_in * W_in) + ih * W_in + iw];
                    acc += val * (*w);
                    ++w;
                }
            }
        }
    }

    if (bias) acc += bias[oc];
    output[((n * C_out + oc) * D_out + od) * H_out * W_out + oh * W_out + ow] = acc;
}

torch::Tensor conv3d_forward_cuda(
    const torch::Tensor& input,
    const torch::Tensor& weight,
    const c10::optional<torch::Tensor>& bias,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> dilation,
    int64_t groups
) {
    int N    = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int C_out = weight.size(0);
    int KD = weight.size(2);
    int KH = weight.size(3);
    int KW = weight.size(4);

    int sd = (int)stride[0], sh = (int)stride[1], sw = (int)stride[2];
    int pd = (int)padding[0], ph = (int)padding[1], pw = (int)padding[2];
    int dd = (int)dilation[0], dh = (int)dilation[1], dw = (int)dilation[2];

    int D_out = (D_in + 2*pd - dd*(KD-1) - 1) / sd + 1;
    int H_out = (H_in + 2*ph - dh*(KH-1) - 1) / sh + 1;
    int W_out = (W_in + 2*pw - dw*(KW-1) - 1) / sw + 1;

    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    const float* in_data = input.data_ptr<float>();
    const float* w_data  = weight.data_ptr<float>();
    const float* b_data  = (bias.has_value() && bias.value().defined()) ? bias.value().data_ptr<float>() : nullptr;
    float* out_data      = output.data_ptr<float>();

    dim3 block(32, 8, 1);
    dim3 grid(
        (W_out + block.x - 1) / block.x,
        (H_out + block.y - 1) / block.y,
        D_out * C_out * N
    );

    // Use the specialized no-padding, stride=1, dilation=1, C_in=3, KD=3,KH=5,KW=7 kernel
    bool is_fast = (C_in == 3 && KD == 3 && KH == 5 && KW == 7 &&
                    sd == 1 && sh == 1 && sw == 1 &&
                    pd == 0 && ph == 0 && pw == 0 &&
                    dd == 1 && dh == 1 && dw == 1 &&
                    groups == 1);

    if (is_fast) {
        conv3d_fast_kernel<<<grid, block>>>(
            in_data, w_data, b_data, out_data,
            N, D_in, H_in, W_in,
            C_out, D_out, H_out, W_out
        );
    } else {
        conv3d_general_kernel<<<grid, block>>>(
            in_data, w_data, b_data, out_data,
            N, C_in, D_in, H_in, W_in,
            C_out, D_out, H_out, W_out,
            KD, KH, KW,
            sd, sh, sw, pd, ph, pw, dd, dh, dw
        );
    }

    return output;
}
